/**
 * Re-reads the subject and indexes it if it still exists and is live; a
 * missing or archived subject is taken out of the index instead (ADR 0007, rule 7).
 */
async function reindexSubject(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
